def transform(grid):
    """Mark the suffix of the first incomplete horizontal monochrome bar with 1."""
    out=[row[:] for row in grid]
    from collections import Counter
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r,row in enumerate(grid):
        fg=[c for c,v in enumerate(row) if v!=bg]
        if fg:
            a,b=min(fg),max(fg)
            if fg==list(range(a,b+1)) and b<len(row)-1:
                # The demonstrations all extend this trailing run to the right edge.
                for c in range(b+1,len(row)):
                    if row[c]==bg: out[r][c]=1
                return out
    return out
